async function populateCitationSections(items){for(const item of items){const isFilename=state.documents.some(d=>String(item.sourceReference||'').toLowerCase().startsWith(String(d.name||'').toLowerCase()));if((item.sourceReference&&!isFilename)||!item.sourceDocument||!item.sourcePage)continue;const doc=state.documents.find(d=>d.name===item.sourceDocument);if(!doc||!doc.name.toLowerCase().endsWith('.pdf'))continue;try{let pdf=window._fieldroomPdf?.[doc.id];if(!pdf){const pdfjs=await loadPdfjs(),response=await fetch(`/api/document/${doc.id}`,{headers:await authHeaders()});if(!response.ok)continue;pdf=await pdfjs.getDocument({data:new Uint8Array(await response.arrayBuffer())}).promise;window._fieldroomPdf=window._fieldroomPdf||{};window._fieldroomPdf[doc.id]=pdf}const page=await pdf.getPage(Math.max(1,Math.min(pdf.numPages,Number(item.sourcePage)))),content=await page.getTextContent(),rowMap=new Map();for(const part of content.items||[]){const value=String(part.str||'').trim();if(!value)continue;const y=Math.round(Number(part.transform?.[5]||0)/2)*2;rowMap.set(y,`${rowMap.get(y)||''} ${value}`.trim())}const rows=[...rowMap.entries()].sort((a,b)=>b[0]-a[0]).map(([,value])=>value.replace(/\s+/g,' ').trim()),sections=rows.map((text,index)=>({text,index,match:text.match(/^(\d+(?:\.\d+){1,3})\s+(.{3,120})$/)})).filter(row=>row.match),terms=`${item.title||''} ${item.notes||''}`.toLowerCase().split(/[^a-z0-9]+/).filter(term=>term.length>3&&!['deliverable','required','contractor','provide'].includes(term));let best=null,bestScore=0;for(const row of rows){const lower=row.toLowerCase(),score=terms.reduce((sum,term)=>sum+(lower.includes(term)?1:0),0);if(score>bestScore){bestScore=score;best=row}}const targetIndex=best?rows.indexOf(best):-1,section=targetIndex>=0?sections.filter(s=>s.index<=targetIndex).at(-1):sections[0];if(section)item.sourceReference=`§ ${section.match[1]} ${section.match[2].trim()}`}catch{}}}
async function runExtraction(options={}){const button=$('#extract-button')||$('#read-plan');if(button){button.disabled=true;button.textContent='Reading drawing…'}try{const floorplans=state.documents.filter(d=>d.category==='floorplan'||state.project.mapConfig?.documentId===d.id);if(!floorplans.length)throw new Error('Upload a full floor plan before extracting room requirements.');const config=state.project.mapConfig||{},documentIds=options.documentIds||state.documents.map(d=>d.id),mapDocumentId=options.mapDocumentId??config.documentId??floorplans[0].id,mapPage=options.mapPage??config.page??1;if(!config.documentId){state.project.mapConfig={documentId:mapDocumentId,page:mapPage}}if(!await saveCurrentProjectNow())throw new Error('Could not save Project Setup before extraction.');const result=await api('/api/extract',{method:'POST',body:JSON.stringify({documentIds,mapDocumentId,mapPage})}),geminiConfigured=state.geminiConfigured,library=projectLibrary;adoptServerState(result.state);projectLibrary=projectLibrary.projects?.length?projectLibrary:library;state.geminiConfigured=geminiConfigured;state.authRequired=runtimeConfig.authRequired;splitPendingShopDrawingBundles();constrainPendingRoomSuggestions();dedupePendingReviewItems();applyProjectSetupExtraction(result);await populateCitationSections((state.suggestions||[]).filter(item=>item.status==='pending'));if(startGuidedReview(false))view='review';else view='documents';persist();render();notify(`${(state.roomSuggestions||[]).filter(room=>room.status==='pending').length} room markers and ${(state.suggestions||[]).filter(item=>item.status==='pending').length} deliverables ready for review.`);if(result.warnings?.length)alert('Review notes from extraction:\n\n'+result.warnings.join('\n'))}catch(e){notify(e.message);if(button){button.disabled=false;button.textContent=button.id==='read-plan'?'✦ Generate from drawing':'✦ Extract room requirements'}}}function saveReviewEdits(form){const values=Object.fromEntries(new FormData(form).entries()),kind=form.dataset.reviewKind,id=form.dataset.reviewId;if(kind==='deliverable'){const item=(state.suggestions||[]).find(s=>s.id===id);if(!item)return false;if(!String(values.title||'').trim()){notify('Enter a deliverable description before saving.');return false}for(const field of ['title','roomNumber','roomName','level','trade','exactLineItem','sourceReference','notes'])item[field]=String(values[field]||'').trim()}else{const item=(state.roomSuggestions||[]).find(s=>s.id===id);if(!item)return false;for(const field of ['roomNumber','roomName','level'])item[field]=String(values[field]||'').trim();item.planPage=Math.max(1,Number.parseInt(values.planPage,10)||1);const names=['mapX','mapY','mapW','mapH'],entered=names.filter(name=>String(values[name]||'').trim()!=='');if(entered.length&&entered.length!==4){notify('Enter all four marker coordinates, or leave all four blank.');return false}if(entered.length===4){const coords=names.map(name=>Number(values[name]));if(coords.some(value=>!Number.isFinite(value)||value<0||value>1000)){notify('Marker coordinates must be between 0 and 1000.');return false}item.mapBox={x:coords[0],y:coords[1],w:coords[2],h:coords[3]}}else item.mapBox=null}persist();return true}
function convertedMapBox(s){if(!s.mapBox||!Number.isFinite(Number(s.mapBox.x))||!Number.isFinite(Number(s.mapBox.y)))return null;return{x:Number(s.mapBox.x)/10,y:Number(s.mapBox.y)/10,w:Math.max(4,Number(s.mapBox.w||70)/10),h:Math.max(4,Number(s.mapBox.h||60)/10)}}
function acceptRoomSuggestion(id,options={}){const s=(state.roomSuggestions||[]).find(x=>x.id===id);if(!s)return;let room=state.project.rooms.find(r=>String(r.number).toLowerCase()===String(s.roomNumber||'').toLowerCase());if(!room){room={id:uid(),number:s.roomNumber||'Room to verify',name:s.roomName||'Unlabeled space',level:s.level||'',mapBox:convertedMapBox(s),mapDocumentId:s.mapDocumentId||state.project.mapConfig?.documentId||null,mapPage:Number(s.planPage||state.project.mapConfig?.page||1),deliverables:[]};state.project.rooms.push(room)}else{room.mapBox=convertedMapBox(s)||room.mapBox;room.mapDocumentId=s.mapDocumentId||room.mapDocumentId;room.mapPage=Number(s.planPage||room.mapPage||1)}s.status='accepted';if(s.mapDocumentId)state.project.mapConfig={documentId:s.mapDocumentId,page:Number(s.planPage||1)};selectedRoomId=room.id;listOpen=false;if(!options.quiet){persist();render();notify('Room marker added. Check and adjust its position against the plan.')}}
function acceptSuggestion(id,options={}){const suggestion=state.suggestions.find(s=>s.id===id);if(!suggestion)return;const deliverable={id:uid(),title:suggestion.title,trade:suggestion.trade,sourceDocument:suggestion.sourceDocument,sourcePage:suggestion.sourcePage,sourceReference:suggestion.sourceReference,notes:suggestion.notes,fieldNotes:'',status:'open',photos:[],sourceDocuments:suggestion.sources};if(suggestion.scope==='general'){state.project.generalDeliverables=state.project.generalDeliverables||[];state.project.generalDeliverables.push(deliverable);suggestion.status='accepted';if(!options.quiet){persist();render();notify('Added to project-wide deliverables.')}}else{let room=state.project.rooms.find(r=>String(r.number).toLowerCase()===String(suggestion.roomNumber||'').toLowerCase());if(!room){room={id:uid(),number:suggestion.roomNumber||'Unassigned',name:suggestion.roomName||'Room to verify',level:suggestion.level||'',mapBox:convertedMapBox(suggestion),mapDocumentId:suggestion.mapDocumentId||state.project.mapConfig?.documentId||null,mapPage:Number(suggestion.planPage||state.project.mapConfig?.page||1),deliverables:[]};state.project.rooms.push(room)}else if(suggestion.mapBox){room.mapBox=convertedMapBox(suggestion);room.mapDocumentId=suggestion.mapDocumentId||room.mapDocumentId;room.mapPage=Number(suggestion.planPage||room.mapPage||1)}room.deliverables=room.deliverables||[];room.deliverables.push(deliverable);suggestion.status='accepted';selectedRoomId=room.id;if(!options.quiet){persist();render();notify('Added to the room matrix.')}}}
function showQr(roomId){const room=roomById(roomId);if(!room)return;const code=room.number||room.id;const url=`${location.origin}/?project=${encodeURIComponent(state.project.id)}&room=${encodeURIComponent(room.id)}`;const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-head"><h2>Room QR · ${esc(code)}</h2><button class="modal-close" aria-label="Close">×</button></div><div id="qr-code" class="qr-center"></div><p class="qr-caption">Scan to open <b>${esc(room.number)} · ${esc(room.name)}</b><br>${esc(url)}</p><div class="notice">QR links work on another device only when it can reach this server. For field use, host the app on a secure, authenticated project network and configure its shared URL.</div><div class="inline" style="justify-content:flex-end;margin-top:14px"><button class="btn secondary" id="copy-room-link">Copy room link</button><button class="btn" onclick="window.print()">Print</button></div></section></div>`;$('.modal-close',root).onclick=()=>root.innerHTML='';$('.modal-backdrop',root).onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};$('#copy-room-link',root).onclick=async()=>{try{await navigator.clipboard.writeText(url);notify('Room link copied.')}catch{prompt('Copy this room link:',url)}};if(window.QRCode)new QRCode($('#qr-code'),{text:url,width:180,height:180,colorDark:'#1d4030',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});else $('#qr-code').innerHTML='<div class="notice">QR generator is unavailable. Connect to the internet to load the QR display library.</div>'}
async function startScanner(){const video=$('#scan-video'),placeholder=$('.video-placeholder');try{if(!('BarcodeDetector'in window))throw new Error('This browser does not support camera QR scanning. Use the room link or room number field below.');const detector=new BarcodeDetector({formats:['qr_code']});scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});video.srcObject=scanStream;video.classList.remove('hidden');placeholder?.classList.add('hidden');await video.play();$('#start-scan').disabled=true;$('#stop-scan').disabled=false;const tick=async()=>{if(!scanStream)return;try{const codes=await detector.detect(video);if(codes.length){stopScanner();lookupRoom(codes[0].rawValue);return}}catch{}requestAnimationFrame(tick)};tick()}catch(e){notify(e.message)}}
function stopScanner(){if(scanStream){scanStream.getTracks().forEach(t=>t.stop());scanStream=null}const video=$('#scan-video');if(video){video.pause();video.srcObject=null;video.classList.add('hidden')}$('.video-placeholder')?.classList.remove('hidden');if($('#start-scan'))$('#start-scan').disabled=false;if($('#stop-scan'))$('#stop-scan').disabled=true}
async function lookupRoom(input){const raw=String(input||'').trim();let target=raw,projectId='';try{const u=new URL(raw,location.origin);target=u.searchParams.get('room')||decodeURIComponent(u.pathname.split('/').filter(Boolean).pop()||'');projectId=u.searchParams.get('project')||''}catch{}if(projectId&&projectId!==projectLibrary.activeId&&projectLibrary.projects.some(p=>p.id===projectId))await switchProject(projectId);const r=state.project.rooms.find(x=>x.id===target||String(x.number).toLowerCase()===target.toLowerCase());if(r){$('#scan-result').innerHTML=`<div class="notice">Room found: <b>${esc(r.number)} · ${esc(r.name)}</b></div><button id="open-scanned-room" class="btn" style="margin-top:9px">Open room deliverables</button>`;$('#open-scanned-room').onclick=()=>openRoom(r.id)}else $('#scan-result').innerHTML='<div class="notice">No room matched that QR link or room code. Check that the QR belongs to this project.</div>'}
function exportCsv(){const headers=['Room','Room name','Level','Trade','Deliverable','Status','Source section','Field notes'];const rows=allDeliverables().map(d=>[d.room.number,d.room.name,d.room.level,d.trade,d.title,d.status,d.sourceReference,d.fieldNotes]);const csv=[headers,...rows].map(row=>row.map(v=>'"'+String(v||'').replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='room-matrix.csv';a.click();URL.revokeObjectURL(a.href)}
async function loadApplication(){try{const incoming=await api('/api/state'),serverLibrary=incoming.projectLibrary;delete incoming.projectLibrary;const serverProjectId=incoming.project.id;state=incoming;if(serverLibrary?.projects?.length)projectLibrary=serverLibrary;else{try{projectLibrary=JSON.parse(localStorage.getItem(PROJECT_LIBRARY_KEY)||'null')||{activeId:'',projects:[]}}catch{projectLibrary={activeId:'',projects:[]}}}if(!Array.isArray(projectLibrary.projects))projectLibrary.projects=[];if(!projectLibrary.projects.length){projectLibrary={activeId:serverProjectId||state.project.id,projects:[{id:serverProjectId||state.project.id,name:state.project.name||'New project',data:cleanProjectData(state)}]}}let serverProject=projectLibrary.projects.find(p=>p.id===serverProjectId);if(!serverProject){serverProject={id:serverProjectId,name:state.project.name||'New project',data:cleanProjectData(state)};projectLibrary.projects.push(serverProject)}if(!projectLibrary.activeId||!projectLibrary.projects.some(p=>p.id===projectLibrary.activeId))projectLibrary.activeId=serverProjectId;if(projectLibrary.activeId!==serverProjectId){const selected=projectLibrary.projects.find(p=>p.id===projectLibrary.activeId);if(selected?.data){state=structuredClone(selected.data);state.revision=Number(incoming.revision||0)}}else serverProject.data=cleanProjectData(state);state.project.mapConfig=state.project.mapConfig||{documentId:'',page:1};migrateGeneralDeliverables();state.suggestions=state.suggestions||[];state.roomSuggestions=state.roomSuggestions||[];splitPendingShopDrawingBundles();constrainPendingRoomSuggestions();dedupePendingReviewItems();const health=await api('/api/health');state.geminiConfigured=health.geminiConfigured;state.authRequired=runtimeConfig.authRequired;saveProjectLibrary();if(!serverLibrary?.projects?.length||projectLibrary.activeId!==serverProjectId)await saveCurrentProjectNow();render();const room=new URLSearchParams(location.search).get('room');if(room){view='scan';render();lookupRoom(location.href)}}catch(e){if(runtimeConfig.authRequired){setSession(null);showLogin(e.message)}else{notify('Could not connect to local project server: '+e.message)}}}
async function init(){try{runtimeConfig=await api('/api/config');authSession=getSession();if(runtimeConfig.authRequired&&!authSession){showLogin();return}if(runtimeConfig.authRequired){const account=await api('/api/account');accountType=account.accountType;if(authSession.accountType&&authSession.accountType!==accountType){setSession(null);showLogin('This account type has changed. Sign in again.');return}authSession.accountType=accountType;setSession(authSession);if(accountType==='field_team')view='matrix'}else accountType='project_manager';await loadApplication()}catch(e){if(runtimeConfig.authRequired){setSession(null);showLogin(e.message)}else notify('Could not connect to the project server: '+e.message)}window.addEventListener('resize',()=>{if(view==='matrix')renderPlanDrawing()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal-root').innerHTML)$('#modal-root').innerHTML=''});}
init();

// Enhance the source viewer with section citations read directly from the cited PDF page.
const openSourceDocumentWithoutSectionScan = openSourceDocument;
openSourceDocument = async function(docId, pageNumber = 1, quote = '') {
  await openSourceDocumentWithoutSectionScan(docId, pageNumber, quote);
  const doc = state.documents.find(item => item.id === docId);
  const pdf = window._fieldroomPdf?.[docId];
  const citation = $('.source-viewer-citation');
  if (!doc || !pdf || !citation) return;
  try {
    const form = $('#guided-item-form');
    const title = String(form?.elements.namedItem('title')?.value || '').toLowerCase();
    const terms = title.split(/[^a-z0-9]+/).filter(term => term.length > 3 && !['architectural','required','deliverable'].includes(term));
    let page = Math.max(1, Math.min(pdf.numPages, Number(pageNumber) || 1));
    if (!Number(pageNumber) && terms.length && pdf.numPages > 1) {
      let bestScore = 0;
      for (let candidate = 1; candidate <= pdf.numPages; candidate++) {
        const content = await (await pdf.getPage(candidate)).getTextContent();
        const text = (content.items || []).map(item => String(item.str || '')).join(' ').toLowerCase();
        const score = terms.reduce((sum, term) => sum + (text.includes(term) ? 1 : 0), 0);
        if (score > bestScore) { bestScore = score; page = candidate; }
      }
      if (page !== 1 && bestScore) await openSourceDocumentWithoutSectionScan(docId, page, quote);
    }
    const content = await (await pdf.getPage(page)).getTextContent();
    const rowMap = new Map();
    for (const item of content.items || []) {
      const value = String(item.str || '').trim();
      if (!value) continue;
      const y = Math.round(Number(item.transform?.[5] || 0) / 2) * 2;
      rowMap.set(y, `${rowMap.get(y) || ''} ${value}`.trim());
    }
    const rows = [...rowMap.entries()].sort((a, b) => b[0] - a[0]).map(([, value]) => value.replace(/\s+/g, ' ').trim());
    const sectionRows = rows.map((text, index) => ({text,index,match:text.match(/^(\d+(?:\.\d+){1,3})\s+(.{3,120})$/)})).filter(row => row.match);
    let selected = null;
    for (const row of rows.map((text,index)=>({text,index}))) {
      if (!terms.some(term => row.text.toLowerCase().includes(term))) continue;
      const prior = sectionRows.filter(section => section.index <= row.index).at(-1) || sectionRows[0];
      if (prior) { selected = {section:prior.match[1], heading:prior.match[2].trim(), row:row.text}; break; }
    }
    const supplied = String(form?.elements.namedItem('sourceReference')?.value || '').trim();
    const sectionList = sectionRows.map(row => `§ ${row.match[1]} ${row.match[2].trim()}`);
    const reference = selected ? `§ ${selected.section} ${selected.heading}` : supplied.replace(/\s+—.*$/,'').trim() || sectionList.join('; ') || 'Section heading not detected on this page.';
    const box = document.createElement('div');
    box.className = 'source-detected-reference';
    const label = document.createElement('b'); label.textContent = 'Cited section';
    const value = document.createElement('span'); value.textContent = reference;
    box.append(label, value);
    if (selected && form && form.elements.namedItem('sourceReference')?.value !== reference) {
      const input = form.elements.namedItem('sourceReference');
      input.value = reference;
      saveGuidedDeliverableEdits(form);
    }
    citation.append(box);
  } catch (error) {
    const box = document.createElement('div'); box.className = 'source-detected-reference'; box.textContent = 'The cited page is open.'; citation.append(box);
  }
};
